from tabulate import tabulate
from proc_info import process_scanner

def display_process_information():
    current_processes_list = process_scanner()
    process_list = []
    headers = ["Sr. No.", "PID", "Process Name", "Username"]
    
    for index, process in enumerate(current_processes_list):    
        process_list.append([index, process.get("pid"), process.get("name"), process.get("username")])

    print(tabulate(process_list, headers = headers, tablefmt = "grid"))

def main():
    display_process_information()

if __name__ == "__main__":
    main()


